#include "ipp_server.h"
static void put16(uint8_t*p,uint16_t v){p[0]=v>>8;p[1]=v;}static void put32(uint8_t*p,uint32_t v){p[0]=v>>24;p[1]=v>>16;p[2]=v>>8;p[3]=v;}static uint16_t get16(const uint8_t*p){return((uint16_t)p[0]<<8)|p[1];}
IppServer::IppServer(uint16_t port):server_(port),port_(port){}void IppServer::begin(const String&n,PrintJobHandler h){printerName_=n;handler_=h;server_.begin();}bool IppServer::running()const{return true;}
size_t IppServer::addStringAttr(uint8_t*o,size_t c,size_t p,uint8_t t,const char*n,const String&v){size_t nl=strlen(n),vl=v.length();if(nl>65535||vl>65535||p+5+nl+vl>c)return 0;o[p++]=t;put16(o+p,nl);p+=2;memcpy(o+p,n,nl);p+=nl;put16(o+p,vl);p+=2;memcpy(o+p,v.c_str(),vl);p+=vl;return p;}
size_t IppServer::addIntegerAttr(uint8_t*o,size_t c,size_t p,uint8_t t,const char*n,uint32_t v){size_t nl=strlen(n);if(nl>65535||p+9+nl>c)return 0;o[p++]=t;put16(o+p,nl);p+=2;memcpy(o+p,n,nl);p+=nl;put16(o+p,4);p+=2;put32(o+p,v);p+=4;return p;}size_t IppServer::addEnumAttr(uint8_t*o,size_t c,size_t p,uint8_t t,const char*n,uint32_t v){return addIntegerAttr(o,c,p,t,n,v);}
bool IppServer::readHttp(WiFiClient&c,uint8_t*b,size_t cap,size_t&bl){bl=0;String l=c.readStringUntil('\n');l.trim();if(!l.startsWith("POST "))return false;size_t cl=0;bool ipp=false;unsigned long d=millis()+3000;while(millis()<d){if(!c.available()){delay(1);continue;}l=c.readStringUntil('\n');l.trim();if(l.isEmpty())break;String x=l;x.toLowerCase();if(x.startsWith("content-length:"))cl=(size_t)x.substring(15).toInt();if(x.startsWith("content-type:")&&x.indexOf("application/ipp")>=0)ipp=true;}if(!ipp||!cl||cl>cap)return false;size_t got=0;d=millis()+5000;while(got<cl&&millis()<d){if(!c.available()){delay(1);continue;}int n=c.read(b+got,cl-got);if(n>0)got+=n;}bl=got;return got==cl;}
bool IppServer::handleIpp(const uint8_t*rq,size_t len,uint8_t*o,size_t cap,size_t&rl){if(len<8||cap<64)return false;uint16_t ver=get16(rq),op=get16(rq+2);uint32_t id=((uint32_t)rq[4]<<24)|((uint32_t)rq[5]<<16)|((uint32_t)rq[6]<<8)|rq[7];if(ver==0||ver>0x0200)ver=0x0200;size_t p=8;if(p>=len||rq[p++]!=1)return false;String fmt="application/octet-stream";while(p+3<=len){uint8_t tag=rq[p++];if(tag==3||tag==4)break;if(p+2>len)return false;uint16_t nl=get16(rq+p);p+=2;if(p+nl+2>len)return false;String name;for(uint16_t i=0;i<nl;i++)name+=(char)rq[p+i];p+=nl;uint16_t vl=get16(rq+p);p+=2;if(p+vl>len)return false;if(name=="document-format"&&vl<128){fmt="";for(uint16_t i=0;i<vl;i++)fmt+=(char)rq[p+i];}p+=vl;}size_t doc=p,r=0;o[r++]=ver>>8;o[r++]=ver;uint16_t status=0;put16(o+r,status);r+=2;put32(o+r,id);r+=4;o[r++]=1;r=addStringAttr(o,cap,r,0x47,"attributes-charset","utf-8");r=addStringAttr(o,cap,r,0x48,"attributes-natural-language","en");if(!r)return false;if(op==0x000B){o[r++]=4;r=addStringAttr(o,cap,r,0x42,"printer-name",printerName_);r=addStringAttr(o,cap,r,0x45,"printer-uri-supported","ipp://hp-print-server.local/ipp/print");r=addStringAttr(o,cap,r,0x49,"document-format-supported","application/PCLm");r=addStringAttr(o,cap,r,0x49,"document-format-supported","image/pwg-raster");r=addEnumAttr(o,cap,r,0x23,"printer-state",3);}else if(op==0x0002){String e;bool ok=handler_&&doc<len&&handler_(rq+doc,len-doc,fmt,e);if(!ok){status=0x0403;put16(o+2,status);r=addStringAttr(o,cap,r,0x41,"status-message",e.isEmpty()?"Print backend unavailable":e);}if(r+1>cap)return false;o[r++]=2;r=addEnumAttr(o,cap,r,0x23,"job-state",ok?3:8);}else{status=0x0501;put16(o+2,status);r=addStringAttr(o,cap,r,0x41,"status-message","Unsupported IPP operation");}if(!r||r+1>cap)return false;o[r++]=3;rl=r;return true;}
void IppServer::handleClient(WiFiClient&c){static uint8_t req[32768],resp[8192];size_t rl=0,ol=0;bool ok=readHttp(c,req,sizeof(req),rl)&&handleIpp(req,rl,resp,sizeof(resp),ol);if(!ok)c.print("HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");else{c.print("HTTP/1.1 200 OK\r\nContent-Type: application/ipp\r\nContent-Length: ");c.print(ol);c.print("\r\nConnection: close\r\n\r\n");c.write(resp,ol);}c.stop();}void IppServer::poll(){WiFiClient c=server_.available();if(c)handleClient(c);}
